from typing import Annotated


async def go_general_threats(
    function_explanation: Annotated[str, "A clear, human-readable explanation of what the Go function does, its purpose, and its role in the application. Should include Go-specific operations, goroutines, and any Go-specific security behaviors."],
    function_body: Annotated[str, "The complete source code of the Go function including all statements, variable assignments, control flow, function calls, Go operations, and any nested logic. This is the actual Go code that will be analyzed for vulnerabilities."], 
    file_path: Annotated[str, "The full relative path from the project root to the file containing this function (e.g., 'main.go', 'pkg/auth/service.go', 'cmd/server/handler.go'). Used for context and reporting."], 
    go_context: Annotated[str, "Additional Go context including the Go version (e.g., Go 1.19, 1.20, 1.21), build tags, and critical Go operations this function handles."],
    list_of_go_threats: Annotated[list[str], "A comprehensive list of Go-specific threats and vulnerabilities to check for during analysis. Each item should be a specific Go threat type (e.g., 'Go Goroutine Vulnerabilities', 'Go Channel Vulnerabilities', 'Go Race Condition Vulnerabilities', 'Go Deadlock Vulnerabilities', 'Go Memory Leak Vulnerabilities', 'Go Resource Leak Vulnerabilities', 'Go Context Vulnerabilities', 'Go Timeout Vulnerabilities', 'Go Cancellation Vulnerabilities', 'Go Panic Vulnerabilities', 'Go Recover Vulnerabilities', 'Go Defer Vulnerabilities', 'Go Interface Vulnerabilities', 'Go Type Assertion Vulnerabilities', 'Go Type Switch Vulnerabilities', 'Go Reflection Vulnerabilities', 'Go Unsafe Vulnerabilities', 'Go Pointer Vulnerabilities', 'Go Slice Vulnerabilities', 'Go Map Vulnerabilities', 'Go String Vulnerabilities', 'Go Byte Vulnerabilities', 'Go Rune Vulnerabilities', 'Go Error Vulnerabilities', 'Go Logging Vulnerabilities', 'Go Monitoring Vulnerabilities', 'Go Auditing Vulnerabilities', 'Go Reporting Vulnerabilities', 'Go Analytics Vulnerabilities', 'Go Mining Vulnerabilities', 'Go Machine Learning Vulnerabilities', 'Go AI Vulnerabilities', 'Go Algorithm Vulnerabilities', 'Go Model Vulnerabilities', 'Go Training Vulnerabilities', 'Go Testing Vulnerabilities', 'Go Validation Vulnerabilities', 'Go Cross-Validation Vulnerabilities', 'Go Overfitting Vulnerabilities', 'Go Underfitting Vulnerabilities', 'Go Bias Vulnerabilities', 'Go Fairness Vulnerabilities', 'Go Discrimination Vulnerabilities', etc.)."] = None
) -> str:
    """
    Analyze a Go function for Go-specific security vulnerabilities and threats.
    
    This function focuses specifically on Go vulnerabilities, Go implementation flaws,
    and Go-specific attack vectors that could lead to race conditions,
    goroutine leaks, or exploitation of Go functionality.
    
    Args:
        function_explanation: Human-readable description of the Go function's purpose and behavior
        function_body: Complete source code of the Go function to be analyzed
        file_path: Full path to the file containing the Go function for context
        go_context: Additional Go context and Go implementation information
        list_of_go_threats: List of specific Go threats to evaluate
        
    Returns:
        str: Detailed Go analysis report including identified vulnerabilities,
             Go-specific attack vector analysis, potential Go impact, and remediation
             recommendations specific to Go security.
             
    Example:
        result = await go_general_threats(
            function_explanation="Concurrent user authentication with goroutines and channels",
            function_body="func authenticateUser(ctx context.Context, user User) error { ... }",
            file_path="pkg/auth/service.go",
            go_context="Go 1.21 with context handling and goroutine management",
            list_of_go_threats=["Go Goroutine Vulnerabilities", "Go Channel Vulnerabilities", "Go Race Condition Vulnerabilities", "Go Deadlock Vulnerabilities"]
        )
        
    Note:
        This function should be used for analyzing Go functions, Go implementations,
        and Go-specific code where vulnerabilities could lead to Go compromise
        or Go functionality exploitation. Focus on Go security best practices.
    """
    msg = f"""
GO GENERAL THREAT ANALYSIS REQUEST

Function Context:
- Go Purpose: {function_explanation}
- File Location: {file_path}
- Go Context: {go_context}
- Go Threats to Evaluate: {', '.join(list_of_go_threats or ['General security threats, Common vulnerabilities, OWASP Top 10'])}

Go Source Code to Analyze:
{function_body}

Please perform a comprehensive Go security analysis focusing on the specified threats and provide detailed findings with Go-specific attack vector analysis, potential Go impact, and remediation guidance specific to Go vulnerabilities and secure Go development practices.
"""

    return msg


